import{z as n,x as p,o as t,c as d,q as l,j as i,D as e,d as r,s as o,S as D,b as s}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"D / T / JK 对照","description":"","frontmatter":{"title":"D / T / JK 对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/flipflop-types.md","filePath":"cs/flipflop-types.md","lastUpdated":1791413859000}'),B={name:"cs/flipflop-types.md"};function A(T,a,c,h,F,f){const E=p("Mermaid");return t(),d("div",null,[a[2]||(a[2]=l('<h1 id="d-t-jk-对照" tabindex="-1">D / T / JK 对照 <a class="header-anchor" href="#d-t-jk-对照" aria-label="Permalink to &quot;D / T / JK 对照&quot;">​</a></h1><div class="epigraph"><p>边沿记忆只要一种：D 触发器。T 与 JK 是输入端的组合包装，便于计数或旧教材画法，不是另一种物理。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/latch-flipflop">锁存与触发器</a>钉死了电平锁存与边沿 D 触发器。本课不重画主从，也不从异步状态机另起。缺口是：教科书还列 T、JK。后课建立保持、寄存器、FSM 默认 <strong>D</strong>；必须说清另外两种只是 D 加门。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>D：边沿把 \\(Q\\leftarrow D\\)。T：边沿若 \\(T=1\\) 则翻转，否则保持——即 \\(D=T\\oplus Q\\)。JK：沿用 \\(J\\) 置 \\(1\\)、\\(K\\) 置 \\(0\\)、皆 1 则翻转；化为 \\(D=J\\bar Q+\\bar K Q\\)。缺口不是新的存储物理，而是激励表与 D 的等价，避免后课以为 CPU 里混用三种硬核。</p><p>异步置位/清零仍是端口，不改变「同步状态走 D」这一默认。</p><h3 id="jk-不是「功能更强所以更适合-cpu」" tabindex="-1">JK 不是「功能更强所以更适合 CPU」 <a class="header-anchor" href="#jk-不是「功能更强所以更适合-cpu」" aria-label="Permalink to &quot;JK 不是「功能更强所以更适合 CPU」&quot;">​</a></h3><p>JK 能表达的下一态 D 全能表达。多两个输入只增加控制器接线。现代标准单元库以 D FF 为主。把 JK 当更通用的记忆，寄存器堆会画错。</p><p><span class="marginnote">Harris 用激励表互化。计数器可用 T（每位进位时翻转）或 D 接增量器。本课不把主从 JK 的 \\(1s\\) 捕获当主干缺陷清单。</span></p><p><span class="marginnote">术语翻译：激励表就是「想让触发器从现态 Q 变到次态 Q+，输入该给什么」的倒查表——反着用的真值表。例如想让 Q 从 1 变 0：D 给 0；T 给 1（翻转）；JK 给 J=0、K=1。三种写法殊途同归，都落到同一个 D 触发器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列现态 \\(Q\\)、输入、次态 \\(Q^+\\)，反推 \\(D\\)。带使能的寄存器：\\(D=E\\cdot D_{\\mathrm{in}}+\\bar E\\cdot Q\\)。T 计数：低位 \\(T=1\\)，高位 \\(T=\\) 低位全 1，与后课计数器一致。</p><p><span class="marginnote">数字实例：用 T 触发器搭三位计数器：最低位每拍翻转（T=1），第二位在低位为 1 时才翻转，第三位在低两位都为 1 时才翻转——数到 011 下一拍变 100，正好逢二进一，与手工数数的进位节奏一致。</span></p>',13)),(t(),i(D,null,{default:e(()=>[o(E,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20LAT%5B%22%E9%94%81%E5%AD%98%20%2F%20%E4%B8%BB%E4%BB%8E%22%5D%20--%3E%20DFF%5B%22%E8%BE%B9%E6%B2%BF%20D%22%5D%0A%20%20DFF%20--%3E%20TFF%5B%22T%20%3D%20D%20%E5%BC%82%E6%88%96%20Q%22%5D%0A%20%20DFF%20--%3E%20JK%5B%22JK%20%E5%8C%96%E6%88%90%20D%22%5D%0A%20%20DFF%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%BB%BA%E7%AB%8B%E4%B8%8E%E4%BF%9D%E6%8C%81%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[r("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,"后课时序不等式写在 D 的 \\(t_{su}\\)、\\(t_h\\)、\\(t_{cq}\\) 上。T/JK 的建立时间要把输入端组合算进路径。FSM 下一态逻辑的输出就是各位 D。本课结束「有哪几种触发器」的词条式罗列，把记忆收成一种元件。",-1)),(t(),i(D,null,{default:e(()=>[o(E,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E8%BE%93%E5%85%A5%20T%22%5D%20--%3E%20X%5B%22%E5%BC%82%E6%88%96%E9%97%A8%3A%20D%20%3D%20T%20%E2%8A%95%20Q%22%5D%0A%20%20FB%5B%22%E5%8F%8D%E9%A6%88%3A%20%E7%8E%B0%E6%80%81%20Q%22%5D%20--%3E%20X%0A%20%20X%20--%3E%20DFF%5B%22%E8%BE%B9%E6%B2%BF%20D%20%E8%A7%A6%E5%8F%91%E5%99%A8%22%5D%0A%20%20CK%5B%22%E6%97%B6%E9%92%9F%E4%B8%8A%E5%8D%87%E6%B2%BF%22%5D%20--%3E%20DFF%0A%20%20DFF%20--%3E%20QP%5B%22%E6%AC%A1%E6%80%81%3A%20T%3D1%20%E7%BF%BB%E8%BD%AC%20%2F%20T%3D0%20%E4%BF%9D%E6%8C%81%22%5D%0A%20%20QP%20--%3E%7C%22Q%20%E5%8F%8D%E9%A6%88%22%7C%20FB%0A%20%20QP%20--%3E%20HZ%5B%22T%20%E6%81%92%E4%B8%BA%201%20%E6%97%B6%3A%20%E8%BE%93%E5%87%BA%E9%A2%91%E7%8E%87%E5%87%8F%E5%8D%8A%2C%20%E5%A4%A9%E7%84%B6%E4%BA%8C%E5%88%86%E9%A2%91%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p><span class="marginnote">常见误区：初学者以为 CPU 里存着 D、T、JK 三种触发器各司其职。实际上现代标准单元库几乎全是 D 触发器，T 与 JK 只活在教材和计数器简写里——把 JK 画进寄存器堆，行家一眼看出是教科书图照抄。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲脉冲触发、不把 ECL 之类工艺触发器请进来。不分析 JK 禁止输入（那是 SR 锁存的问题，边沿 JK 已避开）。</p><p>后课默认：同步状态是边沿 D 触发器；T/JK 仅在画计数器时作为简写。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>物理记忆用 D；T、JK 是输入组合。</li><li>激励表把任意下一态化成 D。</li><li>下一课把 D 的采样窗口写成建立与保持。</li><li>出处：Harris and Harris。</li></ul>',6))])}const _=n(B,[["render",A]]);export{u as __pageData,_ as default};
